// Recover a tuple's true total slot count from the element-type cache. The
// synthetic tuple hash packs first_nslots*1000 + total_nslots in 3-digit fields,
// which OVERFLOWS for any element >= 1000 slots (e.g. (Checker, TypeEntry):
// first=20991, total=21025 -> %1000 = 25, truncating a 167 KB by-value tuple
// RETURN to 200 bytes and leaving env.count uninitialised -> SIGSEGV). The cache
// (registered at every tuple encode site) stores the element types; ty_slot_count
// gives the true size. Falls back to the packed decode for uncached/small tuples.
// Mirrors the override already done in tuple_destructure_from_ptr_x86. Used for
// the return-copy size (ret_agg_nslots) AND the tuple `.0` field-access copy size.
// SIZE recovery is collision-SAFE: the first element is collision-invariant and
// its slot count dwarfs the modulo. We deliberately do NOT recover element TYPES
// from the cache in the .0/.1 path: the overflowed hash is not a unique key, so
// two distinct >=1000-slot tuples (e.g. (Checker,i64) vs (Checker,bool)) can
// collide and yield the wrong element type — which mis-types `.1` and breaks
// type-checking. So `.1` routing/typing is left exactly on the legacy packed path.
fn tup_total_slots_true(tup_hash: i64) -> i64 with Panic, Div, Mut {
    let tci = tup_cache_lookup(tup_hash)
    if tci >= 0 {
        let fs = ty_slot_count(TUP_CACHE_FIRST_TY[tci as usize], TUP_CACHE_FIRST_HASH[tci as usize])
        let ls = ty_slot_count(TUP_CACHE_LAST_TY[tci as usize], TUP_CACHE_LAST_HASH[tci as usize])
        if fs > 0 && ls > 0 { return fs + ls }
    }
    return tup_hash % 1000
}

// True slot count of a tuple's FIRST element (collision-safe: first element is
// invariant across hash collisions). Used to size the `.0` field-access copy,
// which the packed 3-digit decode truncates for first elements >= 1000 slots.
