// Overflow-safe nested ref/option/box hash encoding.
// Direct encoding: base + mut + ty*4 + hash*256. Each wrap level multiplies by 256
// (8 bits). After 3 levels (e.g. &Option<Box<Struct>>), 37-bit name hashes overflow
// i64. To prevent the overflow producing a negative value that collides with
// knowledge_hash_is, we intern overflowing composites into a side-table; the
// returned hash is a sentinel in [rh_intern_base, rh_intern_base+1024) which the
// decoders look up rather than divide.
var RH_INTERN_TY: [i64; 1024] = [0; 1024]
var RH_INTERN_HASH: [i64; 1024] = [0; 1024]
var RH_INTERN_MUT: [i64; 1024] = [0; 1024]
var RH_INTERN_COUNT: i64 = 0

fn rh_intern_base() -> i64 {
    // 2^51 - 1024: sits above 2^50 (ref base) and below 2^51 (unobserved base).
    return 2251799813684224
}

fn rh_intern_is(h: i64) -> bool {
    return h >= rh_intern_base() && h < rh_intern_base() + 1024
}

fn rh_intern_make(inner_ty: i64, inner_hash: i64, is_mut: i64) -> i64 with Mut, Panic {
    var i: i64 = 0
    while i < RH_INTERN_COUNT {
        if RH_INTERN_TY[i as usize] == inner_ty
            && RH_INTERN_HASH[i as usize] == inner_hash
            && RH_INTERN_MUT[i as usize] == is_mut {
            return rh_intern_base() + i
        }
        i = i + 1
    }
    if RH_INTERN_COUNT >= 1024 { return 0 }
    let idx = RH_INTERN_COUNT
    RH_INTERN_TY[idx as usize] = inner_ty
    RH_INTERN_HASH[idx as usize] = inner_hash
    RH_INTERN_MUT[idx as usize] = is_mut
    RH_INTERN_COUNT = RH_INTERN_COUNT + 1
    return rh_intern_base() + idx
}

