// Print "<source-file>:<local-line>" for a token's bundled byte position.
// Scans backwards from TS[tok] to the nearest \x01<path>\x02 marker (start
// of an imported file); newlines between the marker and the token give the
// local line number. If no marker is found, the token is in main and we
// print "main:<line>" using TL[tok] directly.
fn print_src_loc_for_tok(tok: i64) with IO, Mut, Panic {
    let pos = TS[tok as usize]
    if pos < 0 || pos >= SRC_LEN {
        print("<unknown>")
        return
    }
    // Walk backwards: find most recent \x02 (end of marker); the bytes
    // between the preceding \x01 and that \x02 are the source path.
    var scan: i64 = pos
    var marker_end: i64 = -1
    while scan >= 0 {
        if SRC[scan as usize] as i64 == 2 { marker_end = scan; break }
        scan = scan - 1
    }
    if marker_end < 0 {
        // No marker before this position — token is in the main file.
        print("<main>:")
        print_int(TL[tok as usize])
        return
    }
    // Walk further back to find the matching \x01.
    var marker_start: i64 = marker_end - 1
    while marker_start >= 0 && SRC[marker_start as usize] as i64 != 1 {
        marker_start = marker_start - 1
    }
    if marker_start < 0 {
        print("<orphan-marker>:")
        print_int(TL[tok as usize])
        return
    }
    // Print the path (bytes between marker_start+1 and marker_end).
    var pi: i64 = marker_start + 1
    while pi < marker_end {
        print_char(SRC[pi as usize] as i64)
        pi = pi + 1
    }
    print(":")
    // Count newlines from marker_end+1 to pos.
    var local_line: i64 = 1
    var nl_scan: i64 = marker_end + 1
    while nl_scan < pos {
        if SRC[nl_scan as usize] as i64 == 10 { local_line = local_line + 1 }
        nl_scan = nl_scan + 1
    }
    print_int(local_line)
}

