// Field-receiver push: slot_place holds the ADDRESS of the cell storing the Seq
// pointer (a struct field). Copy the pointer into a scratch slot, run the normal
// push (which grows and writes the moved pointer back to that scratch slot), then
// store the final pointer back into the field cell.
fn emit_seq_push_at_place_x86(slot_place: i64, slot_v: i64) with Mut, Panic {
    let slot_pcur = NEXT_SLOT
    NEXT_SLOT = NEXT_SLOT + 1
    emit_load_var(slot_place)                // rax = field addr
    em(0x48); em(0x8b); em(0x00)             // mov rax, [rax]  (current Seq ptr)
    emit_store_var(slot_pcur)
    emit_seq_push_slots_x86(slot_pcur, slot_v)
