                    }
                    cgplan_global_build_deps()
                    cgplan_global_schedule()
                    let slen = CGPLAN_GLOBAL_BLOCK.schedule_len
                    var si: i64 = 0
                    while si < slen {
                        let local_idx = CGPLAN_GLOBAL_BLOCK.schedule[si as usize]
