    let code_len = (*nc).code.len
    let rodata_len = (*nc).rodata.len
    let raw_data_len = (*nc).data.len
    let min_data_len = (*nc).prof_counter_data_base + ((*nc).prof_counter_count * 8)
    let actual_data_len = if raw_data_len < min_data_len { min_data_len } else { raw_data_len }
    let entry = (*nc).entry_offset
    let fn_count = (*nc).fn_count

    let text_offset: i64 = 4096
    let rodata_offset: i64 = align_page(text_offset + code_len)
    let data_offset: i64 = if actual_data_len > 0 { align_page(rodata_offset + rodata_len) } else { 0 }

    var phnum: i64 = 2
    if rodata_len > 0 { phnum = phnum + 1 }
    if actual_data_len > 0 { phnum = phnum + 1 }

    let text_va_base: i64 = base_addr + text_offset

    elf_builder_emit_program_headers_ref(&! bin, entry, base_addr, phnum, elf_machine_x86_64(), code_len, rodata_len, rodata_offset, actual_data_len, data_offset)

    while bin.len < text_offset { elf_emit_byte_ref(&! bin, 0) }
    var ci: i64 = 0
    while ci < code_len {
        elf_emit_byte_ref(&! bin, (*nc).code.bytes[ci as usize] as i64)
        ci = ci + 1
    }

    if rodata_len > 0 {
        while bin.len < rodata_offset { elf_emit_byte_ref(&! bin, 0) }
