pub fn compile_native_x86_linux_to_file(module: &IrModule, output_path: string) -> i32 with IO, Mut, Panic, Div, Alloc {
    var nc = compiler_new()
    compile_module_streaming_begin_into(&! nc, module)
    var fi: i64 = 0
    while fi < (*module).fn_count {
        let fn_body = (*module).functions[fi as usize]
