            return 1
        }
        fi = fi + 1
    }
    compile_module_streaming_finish_into(&! nc, module)
    let elf = finalize_compiled_elf(nc, 4194304)
    let result = native_compile_result_ok_elf(elf.bytes, elf.len, FORMAT_ELF64())
    if !result.ok {
        print("Native compilation failed: ")
        print(result.error_msg)
        print("\n")
        return 1
    }
    if write_file(output_path, result.bytes, result.len) < 0 {
        print("Error: Failed to write native binary to ")
        print(output_path)
        print("\n")
        return 1
    }
    print("Native binary size: ")
    print_int(result.len)
    print(" bytes\n")
    print("Written to ")
    print(output_path)
    print("\n")
    0
}

