fn compile_to_macho_arm64_preview(module: &IrModule, target_spec: NativeTargetSpec) -> NativeCompileResult with Mut, Panic, Div, Alloc {
    let _target = target_spec
    let built = native_v2_build_machine_module(module, true)
    if !built.supported {
        return native_compile_result_error(ERR_BACKEND_NOT_IMPLEMENTED(), "native_v2_unsupported_opcode:" + built.unsupported_detail)
    }

    var c = a64_preview_compiler_new()
    c.fn_count = module.fn_count

    var fi: i64 = 0
    while fi < module.fn_count {
        let pair = a64_preview_compile_function(c, module.functions[fi as usize], built.functions[fi as usize], fi)
        c = pair.0
        if str_len(pair.1) > 0 {
            return native_compile_result_error(ERR_BACKEND_NOT_IMPLEMENTED(), "native_v2_unsupported_opcode:" + pair.1)
        }
        fi = fi + 1
    }

    let main_idx = find_main_index(module)
    if main_idx < 0 {
        return native_compile_result_error(ERR_INVALID_TARGET(), "native_v2_aarch64_missing_main")
    }
    c = a64_preview_emit_entry_trampoline_macos(c, main_idx)
    c = a64_preview_patch_calls(c)

    let text_offset = macho_page_size_for_cpu(MACHO_CPU_ARM64)
    let text_vmaddr: i64 = 4294967296 + text_offset

    var w = macho_writer_new_arm64()
    w.strtab = macho_strtab_init()
    w = macho_add_section(w, macho_make_text_section(text_vmaddr, c.code.len, text_offset))
    var empty_data: [i8; 65536] = [0; 65536]
    let macho = macho_assemble_executable(w, c.code.bytes, c.code.len, empty_data, 0, text_offset + c.entry_offset)
    native_compile_result_ok_narrow(macho.buf, macho.buf_len, FORMAT_MACHO64())
}

        return compile_to_macho_arm64_preview(module, target_spec)
