// ============================================================
// Static refinement: condition guard extraction
// ============================================================
//
// Extract a RefinementPred from a simple boolean expression used as an `if`
// condition.  Recognised forms:
//   <ident> > <int_lit>    →  pred_gt(ident, n)
//   <ident> >= <int_lit>   →  pred_gt_eq(ident, n)
//   <ident> < <int_lit>    →  pred_lt(ident, n)
//   <ident> <= <int_lit>   →  pred_lt_eq(ident, n)
//   <ident> == <int_lit>   →  pred_eq(ident, n)
//   <ident> != <int_lit>   →  pred_neq(ident, n)
//
// Returns (true, pred) on success, (false, _) when the form is unrecognised.
// Only one level of comparison is extracted; conjunctions (&&) are not yet
// handled here (the individual guards already come from the outer env stack).
fn if_cond_extract_pred(opt: Option<Box<Expr> >) -> (bool, RefinementPred) with Mut, Panic, Div {
    let no_pred = (false, empty_refinement_pred())
    match opt {
        None => no_pred
        Some(e) => {
            let expr = *e
            if expr.kind != ExprKind::ExprBinary {
                return no_pred
            }
            // LHS must be an identifier
            let lhs_ok = match expr.left {
                Some(lhs_e) => (*lhs_e).kind == ExprKind::ExprIdent
                None => false
            }
            if !lhs_ok {
                return no_pred
            }
            let lhs_name = match expr.left {
                Some(lhs_e) => (*lhs_e).name
                None => Name { buf: [0; 128], len: 0 }
            }
            // RHS must be an integer literal
            let rhs_ok = match expr.right {
                Some(rhs_e) => (*rhs_e).kind == ExprKind::ExprIntLit
                None => false
            }
            if !rhs_ok {
                return no_pred
            }
            let rhs_val = match expr.right {
                Some(rhs_e) => (*rhs_e).int_val
                None => 0
            }
            // Map BinaryOp → refinement_op
