fn knowledge_hash_make(inner_ty: i64, inner_hash: i64, eps_scaled: i64) -> i64 {
    var eps_code: i64 = 1
    if eps_scaled < -1 {
        eps_code = 0
    } else if eps_scaled >= 0 {
        eps_code = eps_scaled + 2
    }
    let packed = eps_code + (inner_ty * 1048576) + (inner_hash * 67108864)
    return 0 - packed
}

fn knowledge_hash_inner_ty(h: i64) -> i64 with Panic {
    let packed = 0 - h
    return (packed / 1048576) % 64
}

fn knowledge_hash_inner_hash(h: i64) -> i64 with Panic {
    let packed = 0 - h
    return packed / 67108864
}

fn knowledge_hash_eps(h: i64) -> i64 with Panic {
    let packed = 0 - h
    let eps_code = packed % 1048576
    if eps_code == 0 { return -2 }
    if eps_code == 1 { return -1 }
    return eps_code - 2
}

