fn emit_copy_agg_to_ptr_a64(field_ty: i64, field_hash: i64) with Mut, Panic, Div {
    var nslots: i64 = 0
    if field_ty == 8 {
        nslots = arr_storage_slots(field_hash)
    } else if field_ty == 6 {
        let si = st_find(field_hash)
        if si >= 0 { nslots = st_total_size(si) / 8 }
    }
    if nslots <= 0 { return }
    var i: i64 = 0
    while i < nslots {
        em32(0xF9400000 | (i << 10) | (10 << 5) | 11)
        em32(0xF9000000 | (i << 10) | (0 << 5) | 11)
        i = i + 1
    }
}

