// Near-zero guard: if sqrt(x) == 0 pass through eps_a conservatively (avoids div-by-zero).
fn knowledge_emit_intrinsic_sqrt(buf: EpistemicPtxBuf) -> EpistemicPtxBuf with Mut, Panic, Div {
    var out = buf
    out = eptx_push_str(out, "\n// .knowledge.* intrinsic: knowledge_sqrt_f64\n")
    out = eptx_push_str(out, ".func knowledge_sqrt_f64(\n")
    out = eptx_push_str(out, "    .param .f64 _out_val,\n")
    out = eptx_push_str(out, "    .param .f64 _out_eps,\n")
    out = eptx_push_str(out, "    .param .b32 _out_valid,\n")
    out = eptx_push_str(out, "    .param .b64 _out_prov,\n")
    out = eptx_push_str(out, "    .param .f64 _a_val, .param .f64 _a_eps,\n")
    out = eptx_push_str(out, "    .param .b32 _a_valid, .param .b64 _a_prov\n")
    out = eptx_push_str(out, ")\n{\n")
    out = eptx_push_str(out, "    .reg .f64 %lv, %le, %av, %ae;\n")
    out = eptx_push_str(out, "    .reg .pred %lp, %ap, %dp, %tp;\n")
    out = eptx_push_str(out, "    .reg .b64 %lr, %ar;\n")
    out = eptx_push_str(out, "    .reg .f64 %t0;\n")
    out = eptx_push_str(out, "    .reg .b32 %vi;\n\n")
    out = eptx_push_str(out, "    ld.param.f64 %av, [_a_val];\n")
    out = eptx_push_str(out, "    ld.param.f64 %ae, [_a_eps];\n")
    out = eptx_push_str(out, "    ld.param.b32 %vi, [_a_valid]; setp.ne.s32 %ap, %vi, 0;\n")
    out = eptx_push_str(out, "    ld.param.b64 %ar, [_a_prov];\n\n")
    // Domain check: a >= 0
    out = eptx_push_str(out, "    setp.ge.f64 %dp, %av, 0d0000000000000000;\n")
    // Validity: inherited AND domain
    out = eptx_push_str(out, "    and.pred %lp, %ap, %dp;\n")
    // Value: sqrt(a) — NaN for a<0 is safe because %lp=false
    out = eptx_push_str(out, "    sqrt.rn.f64 %lv, %av;\n")
    // Epsilon: u(sqrt(a)) = u(a) / (2*sqrt(a))
    //   Near-zero guard: if sqrt(a)==0, use eps_a (conservative upper bound)
    out = eptx_push_str(out, "    setp.eq.f64 %tp, %lv, 0d0000000000000000;\n")
    out = eptx_push_str(out, "    @%tp  mov.f64 %le, %ae;\n")
    out = eptx_push_str(out, "    @!%tp add.f64 %t0, %lv, %lv;\n")
    out = eptx_push_str(out, "    @!%tp div.rn.f64 %le, %ae, %t0;\n")
    // Provenance: single input — pass through (OR with zero = identity)
    out = eptx_push_str(out, "    mov.b64 %lr, %ar;\n")
    out = eptx_push_str(out, "\n    st.param.f64 [_out_val], %lv;\n")
    out = eptx_push_str(out, "    st.param.f64 [_out_eps], %le;\n")
    out = eptx_push_str(out, "    selp.b32 %vi, 1, 0, %lp;\n")
    out = eptx_push_str(out, "    st.param.b32 [_out_valid], %vi;\n")
    out = eptx_push_str(out, "    st.param.b64 [_out_prov], %lr;\n")
    out = eptx_push_str(out, "    ret;\n}\n")
    out
}

// ============================================================================
// Function 9: Full tiled pipeline — plan → iterate tiles → accumulate
// Implements J . Sigma_N . J^T for N up to 128 via CUTLASS-style blocking.
//
// jacobian:   Jacobian row vector (128 elements, only first n used)
// cov_full:   Upper-triangular covariance matrix (8256 elements = 128*129/2)
// n:          Actual number of variables (≤ 128)
// cfg:        Tile configuration (auto-tuned via tc_auto_tile_size)
//
// Algorithm:
//   1. Build tile plan for the given (n, tile_size)
//   2. For each upper-triangular tile (ti, tj):
//      a. Copy the relevant slice of cov_full into a local tile buffer
//      b. Call tc_propagate_tile for this tile
//   3. Accumulate all tile contributions into a TiledCovResult
// ============================================================================

fn tc_propagate_tiled(jacobian: [f64; 128], cov_full: [f64; 8256], n: i64, cfg: TiledCovConfig) -> TiledCovResult with Mut, Panic, Div {
    let plan = tc_build_plan(cfg)

    var tile_results: [f64; 16] = [0.0; 16]
    var tile_count: i64 = 0

    // Iterate over all upper-triangular tiles
    var tpd = plan.tiles_per_dim
    var ti: i64 = 0
    while ti < tpd {
        var tj: i64 = ti
        while tj < tpd {
            if tile_count < 16 {
                let tl = plan.tiles[tile_count as usize]

                // Copy covariance sub-block for this tile into local buffer
                var cov_tile: [f64; 2080] = [0.0; 2080]
                var ri: i64 = 0
                while ri < tl.size {
                    var ci: i64 = ri
                    while ci < tl.size {
                        let g_row = tl.row_start + ri
                        let g_col = tl.col_start + ci
                        var global_idx: i64 = 0
                        // Global upper-triangular index for (g_row, g_col) in N=n matrix
                        if g_row <= g_col {
                            global_idx = tc_tri_index(n, g_row, g_col)
                        } else {
                            global_idx = tc_tri_index(n, g_col, g_row)
                        }
                        if global_idx < 8256 {
                            let local_idx = tc_tri_index(tl.size, ri, ci)
                            if local_idx < 2080 {
                                cov_tile[local_idx as usize] = cov_full[global_idx as usize]
                            }
                        }
                        ci = ci + 1
                    }
                    ri = ri + 1
                }

                // Compute this tile's contribution to J . Sigma . J^T
                let contrib = tc_propagate_tile(jacobian, cov_tile, tl, n)
                tile_results[tile_count as usize] = contrib
                tile_count = tile_count + 1
            }

            tj = tj + 1
        }
        ti = ti + 1
    }

    tc_accumulate_tiles(tile_results, tile_count)
}

