// T300: [IrLoadImm, IrNop, IrBinOp] → compacts to [IrLoadImm, IrBinOp], count=2.
fn compiler_main_test_compact_basic() -> bool with Mut, Div, Panic {
    var instrs = cp_empty_instrs()
    instrs[0] = ir_load_imm(0, 5)
    instrs[1] = ir_nop()
    instrs[2] = ir_binop(1, 0, BinaryOp::OpAdd, 0)
    let func = cp_make_test_func(instrs, 3)
    let result = ocp_compact_nops(func)
    result.instr_count == 2 && result.instrs[0].op == IrOpcode::IrLoadImm && result.instrs[1].op == IrOpcode::IrBinOp
}

// T301: All NOPs → count=0.
fn compiler_main_test_compact_all_nops() -> bool with Mut, Div, Panic {
    var instrs = cp_empty_instrs()
    instrs[0] = ir_nop()
    instrs[1] = ir_nop()
    instrs[2] = ir_nop()
    let func = cp_make_test_func(instrs, 3)
    let result = ocp_compact_nops(func)
    result.instr_count == 0
}

// T302: No NOPs → count unchanged.
fn compiler_main_test_compact_no_nops() -> bool with Mut, Div, Panic {
    var instrs = cp_empty_instrs()
    instrs[0] = ir_load_imm(0, 1)
    instrs[1] = ir_load_imm(1, 2)
    instrs[2] = ir_binop(2, 0, BinaryOp::OpAdd, 1)
    let func = cp_make_test_func(instrs, 3)
    let result = ocp_compact_nops(func)
    result.instr_count == 3
}

// T303: Interspersed NOPs — preserves instruction order.
fn compiler_main_test_compact_interspersed() -> bool with Mut, Div, Panic {
    var instrs = cp_empty_instrs()
    instrs[0] = ir_nop()
    instrs[1] = ir_load_imm(0, 10)
    instrs[2] = ir_nop()
    instrs[3] = ir_nop()
    instrs[4] = ir_load_imm(1, 20)
    instrs[5] = ir_nop()
    let func = cp_make_test_func(instrs, 6)
    let result = ocp_compact_nops(func)
    result.instr_count == 2 && result.instrs[0].imm_i64 == 10 && result.instrs[1].imm_i64 == 20
}

// T304: Labels survive compaction — label_id is symbolic.
