//   0=NULL, 1=.text, 2=.symtab, 3=.strtab, 4=.note.gnu.property, 5=.shstrtab
    // ----------------------------------------------------------------
    // .note.gnu.property: AVX-512 capability marking
    //   Tells the kernel / dynamic linker this binary requires AVX-512F.
    //   Format: ELF note header (12 B) + name "GNU\0" (4 B) + property (16 B) = 32 B
    //   Note: no PT_NOTE program header yet — section visible to readelf/objdump.
    // ----------------------------------------------------------------
    while bin.len % 8 != 0 {
