    bin = elf_emit_u32(bin, 4)           // namesz = 4 ("GNU\0")
    bin = elf_emit_u32(bin, 16)          // descsz = 16 (one property entry)
    bin = elf_emit_u32(bin, 5)           // type   = NT_GNU_PROPERTY_TYPE_0
    // Name: "GNU\0"
    bin = elf_emit_byte(bin, 71)         // G
    bin = elf_emit_byte(bin, 78)         // N
    bin = elf_emit_byte(bin, 85)         // U
    bin = elf_emit_byte(bin, 0)          // \0
    // Property entry: GNU_PROPERTY_X86_ISA_1_AVX512F
