    bin = elf_emit_u32(bin, 4)           // pr_datasz = 4
    bin = elf_emit_u32(bin, 0x10)        // AVX512F capability bit (bit 4)
    bin = elf_emit_u32(bin, 0)           // padding to 8-byte alignment
